prompt --application/pages/page_00002
begin
wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'Detalle bar'
,p_alias=>'DETALLE-BAR'
,p_step_title=>'Detalle bar'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const API_BASE = ''https://taller-3-bd-x06p.onrender.com/bares'';',
'',
unistr('// Items principales de la p\00E1gina'),
'const ITEM_BAR_ID = ''P_BAR_ID'';',
'const ITEM_AUTOR = ''NOMBRE_BEBEDOR'';',
'const ITEM_COMENTARIO = ''P_COMENTARIO_TEXTO'';',
'',
'// Items de eventos',
'const ITEM_EVENTO_NOMBRE = ''P_EVENTO_NOMBRE'';',
'const ITEM_EVENTO_ARTISTA = ''P_EVENTO_ARTISTA'';',
'const ITEM_EVENTO_COVER = ''P_EVENTO_COVER'';',
'const ITEM_EVENTO_CUPOS = ''P_EVENTO_CUPOS'';',
'const ITEM_EVENTO_DESCUENTO = ''P_EVENTO_DESCUENTO'';',
'const ITEM_EVENTO_HORA_INICIO = ''P_EVENTO_HORA_INICIO'';',
'const ITEM_EVENTO_HORA_FIN = ''P_EVENTO_HORA_FIN'';',
'',
'function getBarId() {',
'  return parseInt(apex.item(ITEM_BAR_ID).getValue(), 10);',
'}',
'',
'function getValue(itemName) {',
'  return apex.item(itemName).getValue() || '''';',
'}',
'',
'function setValue(itemName, value) {',
'  apex.item(itemName).setValue(value);',
'}',
'',
'function escapeHtml(value) {',
'  return String(value ?? '''')',
'    .replace(/&/g, ''&amp;'')',
'    .replace(/</g, ''&lt;'')',
'    .replace(/>/g, ''&gt;'')',
'    .replace(/"/g, ''&quot;'')',
'    .replace(/''/g, ''&#039;'');',
'}',
'',
'/* =========================',
'   COMENTARIOS',
'   ========================= */',
'',
'function cargarComentarios() {',
'  const barId = getBarId();',
'',
'  fetch(`${API_BASE}/${barId}/comentarios`)',
'    .then(res => res.json())',
'    .then(data => {',
'      const container = document.getElementById(''comentarios-container'');',
'',
'      if (!container) {',
'        console.error(''No existe el div comentarios-container'');',
'        return;',
'      }',
'',
'      if (!data || data.length === 0) {',
unistr('        container.innerHTML = ''<p>No hay comentarios a\00FAn.</p>'';'),
'        return;',
'      }',
'',
'      container.innerHTML = data.map(c => `',
'        <div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px;">',
unistr('          <strong>Autor: ${escapeHtml(c.autor || ''An\00F3nimo'')}</strong>'),
'          <span style="color:#888; font-size:0.85em; margin-left:10px;">',
'            ${(c.date || c.fecha) ? new Date(c.date || c.fecha).toLocaleDateString(''es-CO'') : ''''}',
'          </span>',
'          <p style="margin-top:6px;">${escapeHtml(c.texto || '''')}</p>',
'        </div>',
'      `).join('''');',
'    })',
'    .catch(err => {',
'      console.error(err);',
'',
'      const container = document.getElementById(''comentarios-container'');',
'      if (container) {',
'        container.innerHTML = ''<p style="color:red;">Error cargando comentarios.</p>'';',
'      }',
'    });',
'}',
'',
'function enviarComentario() {',
'  const barId = getBarId();',
'  const texto = getValue(ITEM_COMENTARIO);',
'  const autor = getValue(ITEM_AUTOR);',
'',
'  if (!texto.trim()) {',
'    apex.message.showErrors([',
unistr('      { message: ''El comentario no puede estar vac\00EDo.'' }'),
'    ]);',
'    return;',
'  }',
'',
'  fetch(`${API_BASE}/${barId}/comentarios`, {',
'    method: ''POST'',',
'    headers: { ''Content-Type'': ''application/json'' },',
'    body: JSON.stringify({',
'      bar_id: barId,',
'      texto: texto,',
'      autor: autor && autor.trim() ? autor : apex.env.APP_USER',
'    })',
'  })',
'    .then(res => res.json())',
'    .then(() => {',
'      setValue(ITEM_COMENTARIO, '''');',
'      cargarComentarios();',
'    })',
'    .catch(err => {',
'      console.error(err);',
'      apex.message.showErrors([',
'        { message: ''Error enviando el comentario.'' }',
'      ]);',
'    });',
'}',
'',
'/* =========================',
'   EVENTOS',
'   ========================= */',
'',
'function cargarEventos() {',
'  const barId = getBarId();',
'',
'  fetch(`${API_BASE}/${barId}/eventos`)',
'    .then(res => res.json())',
'    .then(data => {',
'      const container = document.getElementById(''eventos-container'');',
'',
'      if (!container) {',
'        console.error(''No existe el div eventos-container'');',
'        return;',
'      }',
'',
'      if (!data || data.length === 0) {',
'        container.innerHTML = ''<p>No hay eventos registrados para este bar.</p>'';',
'        return;',
'      }',
'',
'      container.innerHTML = data.map(e => {',
'        const camposOcultos = [''_id'', ''bar_id'', ''nombre'', ''fecha_creacion''];',
'',
'        const camposExtra = Object.keys(e)',
'          .filter(key => !camposOcultos.includes(key))',
'          .map(key => `',
'            <li>',
'              <strong>${escapeHtml(key.replace(/_/g, '' ''))}:</strong> ${escapeHtml(e[key])}',
'            </li>',
'          `)',
'          .join('''');',
'',
'        return `',
'          <div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px;">',
'            <strong>Evento: ${escapeHtml(e.nombre || ''Evento sin nombre'')}</strong>',
'            <span style="color:#888; font-size:0.85em; margin-left:10px;">',
'              ${e.fecha_creacion ? new Date(e.fecha_creacion).toLocaleDateString(''es-CO'') : ''''}',
'            </span>',
'',
'            ${camposExtra ? `<ul style="margin-top:8px;">${camposExtra}</ul>` : ''''}',
'          </div>',
'        `;',
'      }).join('''');',
'    })',
'    .catch(err => {',
'      console.error(err);',
'',
'      const container = document.getElementById(''eventos-container'');',
'      if (container) {',
'        container.innerHTML = ''<p style="color:red;">Error cargando eventos.</p>'';',
'      }',
'    });',
'}',
'',
'function enviarEvento() {',
'  const barId = getBarId();',
'',
'  const nombre = getValue(ITEM_EVENTO_NOMBRE);',
'  const artista = getValue(ITEM_EVENTO_ARTISTA);',
'  const cover = getValue(ITEM_EVENTO_COVER);',
'  const cupos = getValue(ITEM_EVENTO_CUPOS);',
'  const descuento = getValue(ITEM_EVENTO_DESCUENTO);',
'  const horaInicio = getValue(ITEM_EVENTO_HORA_INICIO);',
'  const horaFin = getValue(ITEM_EVENTO_HORA_FIN);',
'',
'  if (!nombre.trim()) {',
'    apex.message.showErrors([',
'      { message: ''El nombre del evento es obligatorio.'' }',
'    ]);',
'    return;',
'  }',
'',
'  const evento = {',
'    nombre: nombre',
'  };',
'',
'  if (artista.trim()) {',
'    evento.artista = artista;',
'  }',
'',
'  if (cover.trim()) {',
'    evento.cover = parseInt(cover, 10);',
'  }',
'',
'  if (cupos.trim()) {',
'    evento.cupos = parseInt(cupos, 10);',
'  }',
'',
'  if (descuento.trim()) {',
'    evento.descuento = descuento;',
'  }',
'',
'  if (horaInicio.trim()) {',
'    evento.hora_inicio = horaInicio;',
'  }',
'',
'  if (horaFin.trim()) {',
'    evento.hora_fin = horaFin;',
'  }',
'',
'  fetch(`${API_BASE}/${barId}/eventos`, {',
'    method: ''POST'',',
'    headers: { ''Content-Type'': ''application/json'' },',
'    body: JSON.stringify(evento)',
'  })',
'    .then(res => res.json())',
'    .then(() => {',
'      setValue(ITEM_EVENTO_NOMBRE, '''');',
'      setValue(ITEM_EVENTO_ARTISTA, '''');',
'      setValue(ITEM_EVENTO_COVER, '''');',
'      setValue(ITEM_EVENTO_CUPOS, '''');',
'      setValue(ITEM_EVENTO_DESCUENTO, '''');',
'      setValue(ITEM_EVENTO_HORA_INICIO, '''');',
'      setValue(ITEM_EVENTO_HORA_FIN, '''');',
'',
'      cargarEventos();',
'    })',
'    .catch(err => {',
'      console.error(err);',
'      apex.message.showErrors([',
'        { message: ''Error registrando el evento.'' }',
'      ]);',
'    });',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'cargarComentarios();',
'cargarEventos();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
,p_last_updated_by=>'DFELI'
,p_last_upd_yyyymmddhh24miss=>'20260517183819'
);
